    let stdev_trim_label = format!("stdev {trim_range}");

    // Build rendered rows: (label, first, last, range, count, mean, adj_mean).
    struct BandRow {
        label: String,
        first: String,
        last: String,
        range: String,
        count: String,
        mean: String,
        adj_mean: String,
    }

    let mut rows: Vec<BandRow> = Vec::new();
    for i in 0..n_bands {
        if band_count[i] == 0 {
