    println!(
        "{INDENT}{:<label_w$} {:>skip$}{GAP}{trim_stdev_s:>mean_w$} ns",
        stdev_trim_label, "",
    );
}
if let Some((block_mean_s, block_ci_s, block_lsc_s)) = &block_strs {
    println!(
        "{INDENT}{:<label_w$} {:>skip$}{GAP}{block_mean_s:>mean_w$} ns",
