1	//! Settle-anomaly acceptance test (3900X, 2026-07-27): the box
2	//! is bistable (~0.445 vs ~0.489 ns/iter, ~9%), and grades
3	//! degrade whenever a run's window straddles a state
4	//! transition — not in either steady state. One loop of N
5	//! back-to-back runs reproduces it: the loop's own load
6	//! provokes the transition, whichever run straddles it lights
7	//! up a transition detector (drift within a window, repeat
8	//! between attempts), and the later runs ride the state the
9	//! early runs forced — involuntary warmup, the very service
10	//! the dynamic-warmup fix (TODO.md "Dynamic startup warmup")
11	//! makes deliberate. Accepted when no run grades D/F on
12	//! drift/repeat and the median reaches B. The assertion is
13	//! cause-aware on purpose: disturbed/dirty C's are ambient
14	//! contamination (e.g. a concurrent build) and resid is a
15	//! machine trait — neither is the anomaly, and the warmup fix
16	//! removes neither. Grades, not values, are the criterion.
17	//!
18	//! - `#[ignore]`d: machine-specific physics — meaningful only on
19	//!   a box that exhibits the two-state relaxation (the 3900X;
20	//!   the 7600x is single-state and passes vacuously, guarding
21	//!   the warm-exit path post-fix), run alone on a quiet system:
22	//!   `cargo test --test settle_anomaly -- --ignored`
23	//! - Spawns the real binary per run (`CARGO_BIN_EXE_iiac-perf`) —
24	//!   a fresh process per run, like terminal use; `main` is not
25	//!   callable from an integration test and in-process repeats
26	//!   would share warmed state anyway.
27	//! - Env knobs: `IIAC_PERF_BIN` (test another build, e.g. a saved
28	//!   failing 0.23.0-1 once `calibrate` is gone from the tree),
29	//!   `SETTLE_N` (runs, default 10), `SETTLE_GAP` (seconds
30	//!   between runs, default 0 — zero-gap sustains the duty that
31	//!   provokes the transition; rerun with a nonzero gap to probe
32	//!   another duty cycle), `SETTLE_PRINT_ONLY=1` (table only,
33	//!   skip the assertion — for smoke-testing the harness itself).
34	//! - The observable is the calibrate environment letter; when
35	//!   the batch gauge replaces it (0.23.0-4), the parse migrates
36	//!   to the gauge's grade.
37	
38	use std::process::Command;
39	use std::thread::sleep;
40	use std::time::Duration;
41	
42	/// One parsed calibrate run: environment letter, loop/iter ns,
43	/// and the letter's signal breakdown (the parenthesized
44	/// disturbed / dirty win / drift / repeat blob) so a stray C/D
45	/// in the table explains itself.
46	struct CalRun {
47	    letter: char,
48	    loop_iter: String,
49	    signals: String,
50	}
51	
52	impl CalRun {
53	    /// Letter of one named signal from the parenthesized blob
54	    /// (each `, `-separated segment ends with its letter).
55	    fn signal_letter(&self, name: &str) -> Option<char> {
56	        self.signals
57	            .trim_start_matches('(')
58	            .trim_end_matches(')')
59	            .split(", ")
60	            .find(|s| s.starts_with(name))
61	            .and_then(|s| s.chars().last())
62	    }
63	
64	    /// True when this run shows the anomaly's own signature: a
65	    /// state transition graded D/F on either transition
66	    /// detector — drift (within a window) or repeat (between
67	    /// attempts). C-level wobble and the other signals
68	    /// (disturbed / dirty / resid: contamination and machine
69	    /// traits the warmup fix cannot remove) don't count.
70	    fn transition_degraded(&self) -> bool {
71	        ["drift", "repeat"]
72	            .into_iter()
73	            .any(|s| self.signal_letter(s).is_some_and(|l| l == 'D' || l == 'F'))
74	    }
75	}
76	
77	/// Path of the binary under test: `IIAC_PERF_BIN` override or
78	/// the freshly built one.
79	fn bin() -> String {
80	    std::env::var("IIAC_PERF_BIN").unwrap_or_else(|_| env!("CARGO_BIN_EXE_iiac-perf").to_string())
81	}
82	
83	/// Env-var integer knob with default.
84	fn knob(name: &str, default: u64) -> u64 {
85	    std::env::var(name)
86	        .ok()
87	        .and_then(|v| v.parse().ok())
88	        .unwrap_or(default)
89	}
90	
91	/// Run `<bin> calibrate` once and parse the environment letter
92	/// and loop/iter value from its report.
93	fn calibrate_once() -> CalRun {
94	    let out = Command::new(bin())
95	        .arg("calibrate")
96	        .output()
97	        .expect("spawn calibrate");
98	    let text =
99	        String::from_utf8_lossy(&out.stdout).into_owned() + &String::from_utf8_lossy(&out.stderr);
100	    let env_line = text
101	        .lines()
102	        .find_map(|l| l.strip_prefix("  environment"))
103	        .expect("environment line in calibrate output");
104	    let letter = env_line
105	        .trim_start()
106	        .chars()
107	        .next()
108	        .expect("environment letter");
109	    let signals = env_line
110	        .find('(')
111	        .map(|i| env_line[i..].to_string())
112	        .unwrap_or_default();
113	    let loop_iter = text
114	        .lines()
115	        .find_map(|l| {
116	            let rest = l.strip_prefix("  loop/iter")?;
117	            Some(rest.split_whitespace().next()?.to_string())
118	        })
119	        .expect("loop/iter in calibrate output");
120	    CalRun {
121	        letter,
122	        loop_iter,
123	        signals,
124	    }
125	}
126	
127	/// Letter -> ordinal score for the cadence comparison (A best).
128	fn score(letter: char) -> i64 {
129	    match letter {
130	        'A' => 5,
131	        'B' => 4,
132	        'C' => 3,
133	        'D' => 2,
134	        _ => 1,
135	    }
136	}
137	
138	/// Median score of a cadence's runs.
139	fn median_score(runs: &[CalRun]) -> i64 {
140	    let mut scores: Vec<i64> = runs.iter().map(|r| score(r.letter)).collect();
141	    scores.sort_unstable();
142	    scores[scores.len() / 2]
143	}
144	
145	/// Run one cadence: `n` calibrates each preceded by `gap` sleep.
146	fn cadence(tag: &str, n: u64, gap: Duration) -> Vec<CalRun> {
147	    (0..n)
148	        .map(|i| {
149	            sleep(gap);
150	            let run = calibrate_once();
151	            println!(
152	                "{tag}-{idx}  {letter}  loop/iter {li}  {sig}",
153	                idx = i + 1,
154	                letter = run.letter,
155	                li = run.loop_iter,
156	                sig = run.signals
157	            );
158	            run
159	        })
160	        .collect()
161	}
162	
163	#[test]
164	#[ignore = "machine-specific: run alone on a quiet box that shows the relaxation (see module doc)"]
165	fn settle_anomaly_runs_steady() {
166	    let n = knob("SETTLE_N", 10);
167	    let gap = Duration::from_secs(knob("SETTLE_GAP", 0));
168	    println!("bin: {}", bin());
169	    println!(
170	        "knobs (env): SETTLE_N={n} SETTLE_GAP={}s SETTLE_PRINT_ONLY={} IIAC_PERF_BIN={}",
171	        gap.as_secs(),
172	        std::env::var("SETTLE_PRINT_ONLY").is_ok(),
173	        if std::env::var("IIAC_PERF_BIN").is_ok() {
174	            "set"
175	        } else {
176	            "unset (CARGO_BIN_EXE)"
177	        },
178	    );
179	    println!("expect a drift/repeat D/F on the transition run while unfixed:");
180	
181	    let runs = cadence("run", n, gap);
182	
183	    let median = median_score(&runs);
184	    let transitions = runs.iter().filter(|r| r.transition_degraded()).count();
185	    println!("median score: {median}; transition-degraded (drift/repeat at D/F): {transitions}");
186	    if std::env::var("SETTLE_PRINT_ONLY").is_ok() {
187	        return;
188	    }
189	    assert!(
190	        median >= 4,
191	        "settle anomaly: median grade {median} below B (4) \
192	         — runs are measuring mid-transition machine states"
193	    );
194	    assert!(
195	        transitions == 0,
196	        "settle anomaly: {transitions} run(s) with drift or repeat at D/F \
197	         — a state transition landed inside or between measurement windows"
198	    );
199	}
