/// The run grade: signals are facts about the run's batch series,
/// `letter` is the worst signal's grade.
#[derive(Debug)]
pub struct RunGrade {
    /// Samples above their batch's over-floor cut, as a fraction
    /// of all samples in the run.
    pub interference_frac: f64,
    /// Fraction of batches whose mean is [`BURST_TOL`] above the
    /// quietest batch's mean.
    pub burst_frac: f64,
    /// `|late_floor - early_floor| / early_floor`, minimum batch
    /// floor of the run's second half against its first.
    pub drift_frac: f64,
    /// Largest `|Δfloor| / floor` between adjacent batches.
    pub step_frac: f64,
    /// Overall letter, worst signal wins: A, B, C, D, or F.
    pub letter: char,
}

impl RunGrade {
    /// Grade a run from its time-ordered batch summaries; `None`
    /// when the run produced no batches (nothing to grade).
    ///
    /// - `drift` splits the series in half and compares each
    ///   half's *minimum* floor: the floor is the least
    ///   contaminated statistic available, so a half-to-half
    ///   change in it is machine state moving, not load.
    /// - `step` walks adjacent floors for the largest single
    ///   move, catching a transition that drift's endpoints miss.
    /// - A single-batch run scores 0 on both — one floor cannot
    ///   move.
    pub fn from_batches(batches: &[BatchSummary]) -> Option<Self> {
        let (first, rest) = batches.split_first()?;

        let total: u64 = batches.iter().map(|b| b.count).sum();
        let over: u64 = batches.iter().map(|b| b.over_floor).sum();
        let interference_frac = if total == 0 {
            0.0
        } else {
            over as f64 / total as f64
        };

        let quietest = batches
            .iter()
            .map(|b| b.mean_ps)
            .fold(f64::INFINITY, f64::min);
        let hot = batches
            .iter()
            .filter(|b| b.mean_ps > quietest * (1.0 + BURST_TOL))
            .count();
        let burst_frac = hot as f64 / batches.len() as f64;

        let mid = batches.len() / 2;
        let drift_frac = match (min_floor(&batches[..mid]), min_floor(&batches[mid..])) {
            (Some(early), Some(late)) if early > 0.0 => (late - early).abs() / early,
            _ => 0.0,
        };

        let mut step_frac = 0.0f64;
        let mut prev = first.floor_ps as f64;
        for b in rest {
            let cur = b.floor_ps as f64;
            if prev > 0.0 {
                step_frac = step_frac.max((cur - prev).abs() / prev);
            }
            prev = cur;
        }

        let mut grade = Self {
            interference_frac,
            burst_frac,
            drift_frac,
            step_frac,
            letter: 'A',
        };
        grade.letter = score_letter(grade.scores().into_iter().fold(0, u8::max));
        Some(grade)
    }

    /// Per-signal scores in print order: interference, bursts,
    /// drift, step.
    fn scores(&self) -> [u8; 4] {
        [
            score(self.interference_frac, thresholds::INTERFERENCE),
            score(self.burst_frac, thresholds::BURSTS),
            score(self.drift_frac, thresholds::DRIFT),
            score(self.step_frac, thresholds::STEP),
        ]
    }

    /// Letters for the gauge line's printed signals, in print
    /// order — all four composite inputs, so the worst letter on
    /// the line *is* the composite.
    pub fn signal_letters(&self) -> [char; 4] {
        self.scores().map(score_letter)
    }

    /// Warnings for signals at D or worse — one line each, naming
    /// what the signal means for the numbers above it.
    pub fn warnings(&self) -> Vec<String> {
        let names = [
            (
                "interference",
                self.interference_frac,
                "samples sat above their batch floor; the mean and tail carry other work",
            ),
            (
                "bursts",
                self.burst_frac,
                "of batches ran hot; the contamination was not confined to a few moments",
            ),
            (
                "drift",
                self.drift_frac,
                "floor movement from the run's first half to its second; the machine changed state mid-run",
            ),
            (
                "step",
                self.step_frac,
                "floor movement between adjacent batches; a state transition landed inside the run",
            ),
        ];
        names
            .into_iter()
            .zip(self.scores())
            .filter(|&(_, s)| s >= 3)
            .map(|((name, value, gist), s)| {
                format!(
                    "run gauge {name} {}: {:.2}% {gist}",
                    score_letter(s),
                    value * 100.0
                )
            })
            .collect()
    }
}

/// Minimum batch floor (ps) of a slice, `None` when empty.
fn min_floor(batches: &[BatchSummary]) -> Option<f64> {
    batches.iter().map(|b| b.floor_ps).min().map(|f| f as f64)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// One batch with the given floor / mean / census counts.
    fn batch(floor_ps: u64, mean_ps: f64, count: u64, over_floor: u64) -> BatchSummary {
        BatchSummary {
            t_start_s: 0.0,
            t_end_s: 0.05,
            count,
            floor_ps,
            mean_ps,
            max_ps: floor_ps * 2,
            over_floor,
        }
    }

    #[test]
    fn empty_run_has_no_grade() {
        assert!(RunGrade::from_batches(&[]).is_none());
    }

    #[test]
    fn quiet_run_grades_a() {
        let batches: Vec<_> = (0..8).map(|_| batch(1000, 1010.0, 1000, 2)).collect();
        let g = RunGrade::from_batches(&batches).expect("graded");
        assert_eq!(g.letter, 'A');
        assert_eq!(g.signal_letters(), ['A', 'A', 'A', 'A']);
        assert!(g.warnings().is_empty());
    }

    #[test]
    fn single_batch_cannot_move() {
        let g = RunGrade::from_batches(&[batch(1000, 1010.0, 1000, 0)]).expect("graded");
        assert_eq!(g.drift_frac, 0.0);
        assert_eq!(g.step_frac, 0.0);
    }

    #[test]
    fn floor_shift_lights_drift_and_step() {
        // Halves at 1000 / 1100 ps: 10% end-to-end, and the same
        // 10% as one adjacent jump at the seam.
        let mut batches: Vec<_> = (0..4).map(|_| batch(1000, 1010.0, 1000, 0)).collect();
        batches.extend((0..4).map(|_| batch(1100, 1110.0, 1000, 0)));
        let g = RunGrade::from_batches(&batches).expect("graded");
        assert!((g.drift_frac - 0.1).abs() < 1e-9);
        assert!((g.step_frac - 0.1).abs() < 1e-9);
        assert_eq!(g.letter, 'F');
        assert_eq!(g.warnings().len(), 2);
    }

    #[test]
    fn returning_excursion_hides_from_drift_only() {
        // Out and back: the endpoints agree, one batch does not.
        let mut batches: Vec<_> = (0..4).map(|_| batch(1000, 1010.0, 1000, 0)).collect();
        batches.insert(2, batch(1200, 1210.0, 1000, 0));
        let g = RunGrade::from_batches(&batches).expect("graded");
        assert_eq!(g.drift_frac, 0.0);
        assert!((g.step_frac - 0.2).abs() < 1e-9);
    }

    #[test]
    fn census_counts_drive_interference() {
        let batches = [batch(1000, 1010.0, 1000, 100), batch(1000, 1010.0, 1000, 0)];
        let g = RunGrade::from_batches(&batches).expect("graded");
        assert!((g.interference_frac - 0.05).abs() < 1e-9);
        assert_eq!(g.signal_letters()[0], 'B');
    }

    #[test]
    fn hot_batches_drive_bursts() {
        // Three of four means sit above the quietest by > 5%.
        let batches = [
            batch(1000, 1000.0, 1000, 0),
            batch(1000, 1100.0, 1000, 0),
            batch(1000, 1100.0, 1000, 0),
            batch(1000, 1100.0, 1000, 0),
        ];
        let g = RunGrade::from_batches(&batches).expect("graded");
        assert!((g.burst_frac - 0.75).abs() < 1e-9);
        assert_eq!(g.signal_letters()[1], 'D');
    }
}

