impl RunGrade {
    /// Grade a run from its time-ordered batch summaries; `None`
    /// when the run produced no batches (nothing to grade).
    ///
    /// - Both floor signals read `floor_q_ps`, the batch's robust
    ///   low-quantile floor, never its raw min — see
    ///   [`crate::harness::BATCH_FLOOR_Q`] for the measurement
    ///   that settled it.
    /// - `drift` splits the series in half and takes each half's
    ///   *lowest* floor: the quietest moment of each half is the
    ///   half's best view of machine state, so a change between
    ///   them is state moving, not load arriving.
    /// - `step` walks adjacent floors for the largest single
    ///   move, catching a transition that drift's endpoints miss.
    /// - A single-batch run scores 0 on both — one floor cannot
    ///   move.
    pub fn from_batches(batches: &[BatchSummary]) -> Option<Self> {
        let (first, rest) = batches.split_first()?;

        let total: u64 = batches.iter().map(|b| b.count).sum();
        let over: u64 = batches.iter().map(|b| b.over_floor).sum();
        let interference_frac = if total == 0 {
            0.0
        } else {
            over as f64 / total as f64
        };

        let quietest = batches
            .iter()
            .map(|b| b.mean_ps)
            .fold(f64::INFINITY, f64::min);
        let hot = batches
            .iter()
            .filter(|b| b.mean_ps > quietest * (1.0 + BURST_TOL))
            .count();
        let burst_frac = hot as f64 / batches.len() as f64;

        let mid = batches.len() / 2;
        let drift_frac = match (min_floor(&batches[..mid]), min_floor(&batches[mid..])) {
            (Some(early), Some(late)) if early > 0.0 => (late - early).abs() / early,
            _ => 0.0,
        };

        let mut step_frac = 0.0f64;
        let mut step_at_s = first.t_start_s;
        let mut prev = first.floor_q_ps as f64;
        for b in rest {
            let cur = b.floor_q_ps as f64;
            if prev > 0.0 {
                let step = (cur - prev).abs() / prev;
                if step > step_frac {
                    step_frac = step;
                    step_at_s = b.t_start_s;
                }
            }
            prev = cur;
        }

        let mut grade = Self {
            interference_frac,
            burst_frac,
            drift_frac,
            step_frac,
            step_at_s,
            letter: 'A',
        };
        grade.letter = score_letter(grade.scores().into_iter().fold(0, u8::max));
        Some(grade)
    }

